import base64, shutil, datetime, sys, os
ts = datetime.datetime.now().strftime('%Y%m%d_%H%M%S')

def detecta_eol(path):
    with open(path, 'rb') as f:
        data = f.read()
    return '\r\n' if data.count(b'\r\n') > 0 else '\n'

# 1) Cria o arquivo novo AuditoriaConsultas.tsx
# Detecta o padrao de quebra de linha usado nos arquivos vizinhos do projeto
# (para o arquivo novo nascer consistente com o resto do repo local)
ref_dir = 'src/pages/consulta'
ref_files = [f for f in os.listdir(ref_dir) if f.endswith('.tsx')]
eol_projeto = detecta_eol(os.path.join(ref_dir, ref_files[0])) if ref_files else '\n'
newfile_b64_lf = ''
newfile_content = base64.b64decode(newfile_b64_lf).decode('utf-8')
if eol_projeto == '\r\n':
    newfile_content = newfile_content.replace('\r\n', '\n').replace('\n', '\r\n')
with open('src/pages/consulta/AuditoriaConsultas.tsx', 'w', encoding='utf-8', newline='') as f:
    f.write(newfile_content)
print('Criado: src/pages/consulta/AuditoriaConsultas.tsx (EOL detectado:', repr(eol_projeto), ')')

# Edits armazenados em LF; convertidos para o EOL real de cada arquivo na hora de aplicar
edits = [
    {'file': 'src/pages/consulta/ConsultaPage.tsx', 'label': 'Import + state + podeVerAuditoria', 'old_b64': '', 'new_b64': ''},
    {'file': 'src/pages/consulta/ConsultaPage.tsx', 'label': 'Aba na barra de navegacao', 'old_b64': 'ICAgICAgICAgIHtrOidhanVzdGVzJyxsOifimpnvuI8gQ29uZmlndXJhw6fDtWVzJyxtb2R1bG86J2NvbmZpZ3VyYWNvZXMnfSwKICAgICAgICBdLmZpbHRlcih0ID0+ICF1c2VyPy5tb2R1bG9zX3Blcm1pdGlkb3MgfHwgdXNlci5tb2R1bG9zX3Blcm1pdGlkb3MuaW5jbHVkZXModC5tb2R1bG8pKS5tYXAodCA9PiAo', 'new_b64': ''},
    {'file': 'src/pages/consulta/ConsultaPage.tsx', 'label': 'Bloco de renderizacao da aba', 'old_b64': 'ICAgICAgey8qIENvbmZpZ3VyYcOnw7VlcyAobWVudSBkYXMgOCBzdWItw6FyZWFzIGRhIEZhc2UgMSkgKi99CiAgICAgIHt0YWIgPT09ICdhanVzdGVzJyAmJiA8Q29uZmlndXJhY29lc0NvbnN1bHRhcy8+fQ==', 'new_b64': ''},
    {'file': 'src/pages/consulta/PermissoesConsultas.tsx', 'label': 'Modulo auditoria na lista de permissoes', 'old_b64': 'ICB7IGtleTogJ2NsaW5pY2EnLCBsYWJlbDogJ0Nsw61uaWNhJyB9LAogIHsga2V5OiAnaW5pY2lvX3dpZGdldHMnLCBsYWJlbDogJ0luw61jaW8gLyBXaWRnZXRzJyB9LApdOw==', 'new_b64': ''},
]

backed_up = set()
for e in edits:
    fname = e['file']
    if fname not in backed_up:
        shutil.copy(fname, fname + f'.bak_{ts}')
        backed_up.add(fname)
        print('Backup:', fname + f'.bak_{ts}')

ok = True
for e in edits:
    fname = e['file']
    eol = detecta_eol(fname)
    old = base64.b64decode(e['old_b64']).decode('utf-8')
    new = base64.b64decode(e['new_b64']).decode('utf-8')
    if eol == '\r\n':
        old = old.replace('\r\n', '\n').replace('\n', '\r\n')
        new = new.replace('\r\n', '\n').replace('\n', '\r\n')
    with open(fname, 'r', encoding='utf-8', newline='') as f:
        content = f.read()
    count = content.count(old)
    if count != 1:
        print(f'AVISO: {count} ocorrencias (esperado 1): {e["label"]} em {fname}')
        ok = False
        continue
    content = content.replace(old, new)
    with open(fname, 'w', encoding='utf-8', newline='') as f:
        f.write(content)
    print('OK:', e['label'], 'em', fname, '(EOL:', repr(eol), ')')

if ok:
    print()
    print('Tudo aplicado com sucesso. Proximo passo: npm run build')
else:
    print()
    print('ATENCAO: algum patch nao aplicou. NAO faca commit ainda -- me avise com a mensagem acima.')
    sys.exit(1)